        "line": "p1:L27"
      },
      {
        "group": "환경",
        "class_code": "ENV_AQ_CHRONIC",
        "category": "3",
        "raw": "만성 수생환경, 구분 3",
        "line": "p1:L28"
      }
    ],
    "signal_word": "위험",
    "pictograms": [
      {
        "code": "GHS03"
      },
      {
        "code": "GHS05"
      },
      {
        "code": "GHS06"
      }
    ],
    "h_statements": [
      {
        "code": "H271",
        "text": "화재 또는 폭발을 일으킬 수 있음: 강산화제.",
        "line": "p2:L5"
      },
      {
        "code": "H290",
        "text": "금속을 부식시킬 수 있음.",
        "line": "p2:L6"
      },
      {
        "code": "H314",
        "text": "피부에 심한 화상과 눈에 손상을 일으킴.",
        "line": "p2:L7"
      },
      {
        "code": "H318",
        "text": "눈에 심한 손상을 일으킴.",
        "line": "p2:L8"
      },
      {
        "code": "H331",
        "text": "흡입하면 유독함.",
        "line": "p2:L9"
      },
      {
        "code": "H412",
        "text": "장기적인 영향에 의해 수생생물에게 유해함.",
        "line": "p2:L10"
      }
    ],
    "p_statements": [
      {
        "code": "P210",
        "type": "예방",
        "text": "열, 고온의 표면, 스파크, 화염 및 그 밖의 점화원으로부터 멀리하시오. 금연.",
        "line": "p2:L13"
      },
      {
        "code": "P220",
        "type": "예방",
        "text": "의류 및 그 밖의 가연성 물질로부터 멀리하시오.",
        "line": "p2:L14"
      },
      {
        "code": "P234",
        "type": "예방",
        "text": "원래의 용기에만 보관하시오.",
        "line": "p2:L15"
      },
      {
        "code": "P260",
        "type": "예방",
        "text": "분진, 흄, 가스, 미스트, 증기, 스프레이를 흡입하지 마시오.",
        "line": "p2:L16"
      },
      {
        "code": "P261",
        "type": "예방",
        "text": "분진, 흄, 가스, 미스트, 증기, 스프레이의 흡입을 피하시오.",
        "line": "p2:L17"
      },
      {
        "code": "P264",
        "type": "예방",
        "text": "취급 후에는 오염된 신체 부위를 철저히 씻으시오.",
        "line": "p2:L18"
      },
      {
        "code": "P271",
        "type": "예방",
        "text": "옥외 또는 환기가 잘 되는 곳에서만 취급하시오.",
        "line": "p2:L19"
      },
      {
        "code": "P273",
        "type": "예방",
        "text": "환경으로 배출하지 마시오.",
        "line": "p2:L20"
      },
      {
        "code": "P280",
        "type": "예방",
        "text": "보호장갑, 보호의, 보안경, 안면보호구를 착용하시오.",
        "line": "p2:L21"
      },
      {
        "code": "P283",
        "type": "예방",
        "text": "방화복 또는 방염복을 입으시오.",
        "line": "p2:L22"
      },
      {
        "code": "P301+P330+P331",
        "type": "대응",
        "text": "삼켰다면 입을 씻어내시오. 토하게 하지 마시오.",
        "line": "p2:L24"
      },
      {
        "code": "P303+P361+P353",
        "type": "대응",
        "text": "피부(또는 머리카락)에 묻으면: 오염된 모든 의류를 즉시 벗으시오. 피부를 물로 씻으시오. 또는 샤워하시오.",
        "line": "p2:L25"
      },
      {
        "code": "P304+P340",
        "type": "대응",
        "text": "흡입하면: 신선한 공기가 있는 곳으로 옮기고 호흡하기 쉬운 자세로 안정을 취하시오.",
        "line": "p2:L26"
      },
      {
        "code": "P305+P351+P338",
        "type": "대응",
        "text": "눈에 묻으면: 몇 분간 물로 조심해서 씻으시오. 가능하면 콘택트렌즈를 제거하시오. 계속 씻으시오.",
        "line": "p2:L27"
      },
      {
        "code": "P306+P360",
        "type": "대응",
        "text": "의류에 묻으면: 의류를 벗기 전에 오염된 의류 및 피부를 다량의 물로 즉시 씻어내시오.",
        "line": "p2:L28"
      },
      {
        "code": "P310",
        "type": "대응",
        "text": "즉시 의료기관, 의사의 진찰을 받으시오.",
        "line": "p2:L29"
      },
      {
        "code": "P311",
        "type": "대응",
        "text": "의료기관, 의사의 진찰을 받으시오.",
        "line": "p2:L30"
      },
      {
        "code": "P321",
        "type": "대응",
        "text": "즉시 의학적인 조치, 의료기관 처치를 하시오.",
        "line": "p2:L31"
      },
      {
        "code": "P363",
        "type": "대응",
        "text": "다시 사용 전 오염된 의류를 세척하시오.",
        "line": "p2:L32"
      },
      {
        "code": "P370+P378",
        "type": "대응",
        "text": "화재 시: 불을 끄기 위해 적절한 소화제를 사용하시오.",
        "line": "p2:L33"
      },
      {
        "code": "P371+P380+P375",
        "type": "대응",
        "text": "대형 화재 시: 주변 지역의 사람을 대피시키시오. 폭발의 위험이 있으므로 거리를 유지하면서 불을 끄시오.",
        "line": "p2:L34"
      },
      {
        "code": "P390",
        "type": "대응",
        "text": "물질손상을 방지하기 위해 누출물을 흡수시키시오.",
        "line": "p2:L35"
      },
      {
        "code": "P403+P233",
        "type": "저장",
        "text": "환기가 잘 되는 곳에 보관하시오. 용기를 단단히 밀폐하시오.",
        "line": "p2:L37"
      },
      {
        "code": "P405",
        "type": "저장",
        "text": "잠금장치를 하여 저장하시오.",
        "line": "p2:L38"
      },
      {
        "code": "P406",
        "type": "저장",
        "text": "금속부식성 물질이므로 제조자 또는 행정관청에서 정한 내부식성 용기 등에 보관하시오.",
        "line": "p2:L39"
      },
      {
        "code": "P420",
        "type": "저장",
        "text": "격리하여 보관하시오.",
        "line": "p2:L40"
      },
      {
        "code": "P501",
        "type": "폐기",
        "text": "폐기물 관련 법령에 따라 내용물 또는 용기를 폐기하시오.",
        "line": "p3:L5"
      }
    ],
    "other_hazards": [
      {
        "value": "해당없음",
        "line": "p3:L7"
      }
    ],
